import type { INestApplication } from '@nestjs/common';
import { NunjucksEngine } from '@nestvexa/engine-nunjucks';
import { registerViewEngine } from 'nestvexa';
import { resolve } from 'node:path';

/**
 * Generated by `nestvexa add engine nunjucks`. Views ending in `.njk` under
 * views/ render with this adapter (`@Render('pages/home.njk')`); `.hbs`
 * views keep using the default Handlebars engine.
 */
export const nunjucksEngine = new NunjucksEngine({
  root: resolve(process.cwd(), 'views'),
  cache: process.env['NODE_ENV'] === 'production',
  defaultLayout: 'layouts/main',
});

/**
 * Registers the `.njk` view engine on Express or Fastify. Call before
 * `app.listen()`; dispose the engine on shutdown if you create it per test.
 */
export async function registerNunjucksEngine(app: INestApplication): Promise<void> {
  await registerViewEngine(app, 'njk', nunjucksEngine);
}
